        ]
      },
      {
        "description": "Percent of English learners in the district. Controls for language-related factors affecting test scores.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english"
        ]
      },
      {
        "description": "Computers per student (district technology resource). Computed as (computer / students).",
